<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CarrierOnboarding;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('CARRIER_REVIEW_QUEUE_VIEW');$id=(int)($_GET['id']??0);$errors=[];$record=CarrierOnboarding::review($id);if(!$record){http_response_code(404);exit('Carrier verification not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{CarrierOnboarding::decide($id,(int)Auth::user()['id'],(string)($_POST['decision']??''),(string)($_POST['reason']??''));header('Location: '.Url::to('operations/carriers.php?saved=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Carrier Verification';require BASE_PATH.'/app/Views/layout/header.php';$name=$record['company_name']?:$record['user_name'];?><div class="page-head"><div><h1><?=h($name)?></h1><p><?=h(str_contains($record['case_type'],'company')?'Carrier company':'Individual truck owner')?> · <?=h($record['verification_case_ref'])?></p></div><span class="badge"><?=h($record['status'])?></span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="card"><dl class="definition"><?php if($record['company_id']):?><dt>Registration</dt><dd><?=h($record['registration_number'].' · '.$record['registration_country'])?></dd><?php endif;?><dt>TIN</dt><dd><?=h($record['tin_number'])?></dd><dt>Business licence</dt><dd><?=h($record['business_license_number'])?><?=h($record['business_license_expiry']?' · expires '.$record['business_license_expiry']:'')?></dd><dt>Insurance</dt><dd><?=h($record['insurance_provider'].' · '.$record['insurance_policy_number'])?><?=h($record['insurance_expiry']?' · expires '.$record['insurance_expiry']:'')?></dd></dl></div><?php if($record['status']==='pending'):?><div class="decision-grid" style="margin-top:18px"><?php if(Auth::can('CARRIER_REVIEW_APPROVE')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="approved"><div class="field"><label>Approval note <span class="muted">(optional)</span></label><textarea name="reason" maxlength="2000" rows="4"></textarea></div><button class="button" style="margin-top:12px">Approve and activate carrier</button></form><?php endif;?><?php if(Auth::can('CARRIER_REVIEW_REJECT')):?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="decision" value="rejected"><div class="field"><label>Rejection reason</label><textarea name="reason" minlength="10" maxlength="4000" rows="4" required></textarea></div><button class="button danger" style="margin-top:12px">Reject carrier</button></form><?php endif;?></div><?php else:?><div class="notice">This verification has already been decided.</div><?php endif;?><?php require BASE_PATH.'/app/Views/layout/footer.php';
